SELECT jsonb_build_object(
'auth_functions',(SELECT jsonb_agg(jsonb_build_object('name',p.proname,'owner',pg_get_userbyid(p.proowner),'security_definer',p.prosecdef,'config',p.proconfig,'installer_execute',has_function_privilege(current_user,p.oid,'EXECUTE'))) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='auth' AND p.proname IN ('uid','jwt')),
'creator_defaults',(SELECT coalesce(jsonb_agg(jsonb_build_object('creator',pg_get_userbyid(d.defaclrole),'schema',coalesce(n.nspname,'GLOBAL'),'type',d.defaclobjtype,'acl',d.defaclacl::text)),'[]'::jsonb) FROM pg_default_acl d LEFT JOIN pg_namespace n ON n.oid=d.defaclnamespace WHERE pg_get_userbyid(d.defaclrole)='postgres'),
'existing_definers',(SELECT jsonb_agg(jsonb_build_object('name',p.proname,'arguments',pg_get_function_identity_arguments(p.oid),'owner',pg_get_userbyid(p.proowner),'config',p.proconfig,'definition_md5',md5(pg_get_functiondef(p.oid)),'authenticated_execute',has_function_privilege('authenticated',p.oid,'EXECUTE'),'anon_execute',has_function_privilege('anon',p.oid,'EXECUTE'),'literal_workspace_reference',position('workspace' IN lower(p.prosrc))>0,'possible_dynamic_sql',position('execute' IN lower(p.prosrc))>0)) FROM pg_proc p WHERE p.pronamespace='public'::regnamespace AND p.prosecdef),
'personal_tables',(SELECT jsonb_agg(jsonb_build_object('name',c.relname,'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity)) FROM pg_class c WHERE c.relnamespace='public'::regnamespace AND c.relname IN ('tasks','events','profiles','medication_items'))
) AS metadata;
